insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('f4d78df5-0331-5249-b2f7-f63bc60a93fd', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 0, 'Sara wakes up early on Monday.', 'تستيقظ سارة مبكراً يوم الاثنين.', '[{"w":"Sara","ar":"سارة"},{"w":"wakes","ar":"يستيقظ / يوقظ"},{"w":"up","ar":"(wake up: يستيقظ)"},{"w":"early","ar":"مبكراً"},{"w":"on","ar":"على / في (الأيام)"},{"w":"Monday","ar":"الاثنين"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('56fc6ab7-232c-546f-b22e-09c5786de864', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 1, 'Today is her first day at the bakery.', 'اليوم هو أول يوم لها في المخبز.', '[{"w":"Today","ar":"اليوم"},{"w":"is","ar":"يكون / هو"},{"w":"her","ar":"ها / لها"},{"w":"first","ar":"أول / أولاً"},{"w":"day","ar":"يوم"},{"w":"at","ar":"في / عند"},{"w":"the","ar":"الـ"},{"w":"bakery","ar":"مخبز"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('8ab179c3-9656-5c64-91ee-81f338704690', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 2, 'The air outside is cold and quiet.', 'الجو في الخارج بارد وهادئ.', '[{"w":"The","ar":"الـ"},{"w":"air","ar":"الهواء"},{"w":"outside","ar":"في الخارج"},{"w":"is","ar":"يكون / هو"},{"w":"cold","ar":"بارد"},{"w":"and","ar":"و"},{"w":"quiet","ar":"هادئ"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('7ae0c72c-5c32-5a7c-bc81-c205a5d6b175', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 3, 'Her boss smiles and gives her a white apron.', 'مديرها يبتسم ويعطيها مريلة بيضاء.', '[{"w":"Her","ar":"ها / لها"},{"w":"boss","ar":"المدير"},{"w":"smiles","ar":"يبتسم"},{"w":"and","ar":"و"},{"w":"gives","ar":"يعطي"},{"w":"her","ar":"ها / لها"},{"w":"a","ar":"ـًا / واحد"},{"w":"white","ar":"أبيض"},{"w":"apron","ar":"مريلة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('39f7fe87-b5ef-5caa-8f70-b981b8059dd1', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 4, 'She learns how to make bread with her hands.', 'تتعلم كيف تصنع الخبز بيديها.', '[{"w":"She","ar":"هي"},{"w":"learns","ar":"تتعلم"},{"w":"how","ar":"كيف / كم"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"make","ar":"تصنع"},{"w":"bread","ar":"خبز"},{"w":"with","ar":"مع / بـ"},{"w":"her","ar":"ها / لها"},{"w":"hands","ar":"يدين"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('1131b19d-bb5b-5d5f-8eb2-f852482f8d8d', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 5, 'At eight o''clock, the first customers arrive.', 'في الساعة الثامنة، يصل أول الزبائن.', '[{"w":"At","ar":"في / عند"},{"w":"eight","ar":"ثمانية"},{"w":"o''clock","ar":"الساعة (بالضبط)"},{"w":"the","ar":"الـ"},{"w":"first","ar":"أول / أولاً"},{"w":"customers","ar":"الزبائن"},{"w":"arrive","ar":"يصلون"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('ff56b6f8-f0b2-5fb9-8bc8-a36734f86126', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 6, 'An old man asks for two warm rolls.', 'رجل كبير في السن يطلب رغيفين دافئين.', '[{"w":"An","ar":"ـًا / واحد"},{"w":"old","ar":"كبير في السن / قديم"},{"w":"man","ar":"رجل"},{"w":"asks","ar":"يطلب / يسأل"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"two","ar":"اثنان"},{"w":"warm","ar":"دافئ"},{"w":"rolls","ar":"أرغفة صغيرة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('2ebbd07f-6c29-522f-9c4e-ef2ed3e68c1a', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 7, 'Sara puts them in a bag and says thank you.', 'تضعهما سارة في كيس وتقول شكراً.', '[{"w":"Sara","ar":"سارة"},{"w":"puts","ar":"يضع"},{"w":"them","ar":"هم / ها"},{"w":"in","ar":"في"},{"w":"a","ar":"ـًا / واحد"},{"w":"bag","ar":"حقيبة / كيس"},{"w":"and","ar":"و"},{"w":"says","ar":"يقول"},{"w":"thank","ar":"شكراً (thank you)"},{"w":"you","ar":"أنت"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('af2e6f17-d3a2-53ee-b101-3360b3bc5f7d', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 8, 'By the afternoon, her feet are tired.', 'بحلول العصر، تكون قدماها متعبتين.', '[{"w":"By","ar":"بحلول / بـ"},{"w":"the","ar":"الـ"},{"w":"afternoon","ar":"العصر / بعد الظهر"},{"w":"her","ar":"ها / لها"},{"w":"feet","ar":"قدمان"},{"w":"are","ar":"تكون / هم"},{"w":"tired","ar":"متعب"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('a357f229-bf0a-57a5-bd6d-63518d932db8', '028de7cb-8398-5abe-9ed1-2d31580f29b4', 9, 'But she is happy, and she wants to come back tomorrow.', 'لكنها سعيدة، وتريد أن تعود غداً.', '[{"w":"But","ar":"لكن"},{"w":"she","ar":"هي"},{"w":"is","ar":"يكون / هو"},{"w":"happy","ar":"سعيدة"},{"w":"and","ar":"و"},{"w":"she","ar":"هي"},{"w":"wants","ar":"تريد"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"come","ar":"يأتي"},{"w":"back","ar":"عائداً (come back: يعود)"},{"w":"tomorrow","ar":"غداً"}]'::jsonb) on conflict do nothing;
insert into public.units (id, type, slug, title_en, title_ar, description_en, description_ar, level, theme, emoji, sort_order)
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('75d9c4a4-ef64-5ea8-86ef-05f778856915', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 0, 'Omar comes home late after work.', 'يعود عمر إلى البيت متأخراً بعد العمل.', '[{"w":"Omar","ar":"عمر"},{"w":"comes","ar":"يعود / يأتي"},{"w":"home","ar":"البيت"},{"w":"late","ar":"متأخراً"},{"w":"after","ar":"بعد"},{"w":"work","ar":"العمل / أعمل"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('83d36830-000c-56a5-be98-ac7655405daf', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 1, 'He puts his hand in his pocket, but the key is not there.', 'يضع يده في جيبه، لكن المفتاح ليس هناك.', '[{"w":"He","ar":"هو"},{"w":"puts","ar":"يضع"},{"w":"his","ar":"ـه (له)"},{"w":"hand","ar":"يد"},{"w":"in","ar":"في"},{"w":"his","ar":"ـه (له)"},{"w":"pocket","ar":"جيب"},{"w":"but","ar":"لكن"},{"w":"the","ar":"الـ"},{"w":"key","ar":"المفتاح"},{"w":"is","ar":"يكون / هو"},{"w":"not","ar":"لا / ليس"},{"w":"there","ar":"هناك"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('f470de07-e905-5ae2-9b73-74f35eeb5c31', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 2, 'He checks his bag and his car.', 'يفحص حقيبته وسيارته.', '[{"w":"He","ar":"هو"},{"w":"checks","ar":"يفحص"},{"w":"his","ar":"ـه (له)"},{"w":"bag","ar":"حقيبة / كيس"},{"w":"and","ar":"و"},{"w":"his","ar":"ـه (له)"},{"w":"car","ar":"سيارة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('a7663dd2-9a44-5b14-a383-5b9bfd43305d', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 3, 'Nothing. The key is gone.', 'لا شيء. المفتاح ضاع.', '[{"w":"Nothing","ar":"لا شيء"},{"w":"The","ar":"الـ"},{"w":"key","ar":"المفتاح"},{"w":"is","ar":"يكون / هو"},{"w":"gone","ar":"ضائع / ذهب"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('5f815cef-31ab-5968-84ff-f47ce9a5d82a', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 4, 'He calls his sister, but she does not answer.', 'يتصل بأخته، لكنها لا ترد.', '[{"w":"He","ar":"هو"},{"w":"calls","ar":"يتصل"},{"w":"his","ar":"ـه (له)"},{"w":"sister","ar":"أخت"},{"w":"but","ar":"لكن"},{"w":"she","ar":"هي"},{"w":"does","ar":"(فعل مساعد للنفي/السؤال)"},{"w":"not","ar":"لا / ليس"},{"w":"answer","ar":"يرد / يجيب"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('9297dc7f-c5b7-5547-92bf-23459468be39', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 5, 'Then he hears a small sound from the window above.', 'ثم يسمع صوتاً خفيفاً من النافذة في الأعلى.', '[{"w":"Then","ar":"ثم"},{"w":"he","ar":"هو"},{"w":"hears","ar":"يسمع"},{"w":"a","ar":"ـًا / واحد"},{"w":"small","ar":"صغير"},{"w":"sound","ar":"صوت"},{"w":"from","ar":"من"},{"w":"the","ar":"الـ"},{"w":"window","ar":"النافذة"},{"w":"above","ar":"في الأعلى / فوق"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('170d22aa-0fbd-5edd-88ce-7ed80306850d', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 6, 'His neighbor is holding something shiny.', 'جاره يمسك شيئاً لامعاً.', '[{"w":"His","ar":"ـه (له)"},{"w":"neighbor","ar":"جار"},{"w":"is","ar":"يكون / هو"},{"w":"holding","ar":"يمسك"},{"w":"something","ar":"شيء ما"},{"w":"shiny","ar":"لامع"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('f557c5d8-3749-5dd6-a48e-d3f8bf84c003', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 7, '"Is this yours? It was on the stairs."', '"هل هذا لك؟ كان على الدرج."', '[{"w":"Is","ar":"يكون / هو"},{"w":"this","ar":"هذا"},{"w":"yours","ar":"لك"},{"w":"It","ar":"هو / هي"},{"w":"was","ar":"كان / كانت"},{"w":"on","ar":"على / في (الأيام)"},{"w":"the","ar":"الـ"},{"w":"stairs","ar":"الدرج"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('afb9c53a-967b-5fa0-b00c-802af070140c', '25ba7d97-f3d2-58a2-9d85-c8ae6c184681', 8, 'Omar laughs and thanks him three times.', 'يضحك عمر ويشكره ثلاث مرات.', '[{"w":"Omar","ar":"عمر"},{"w":"laughs","ar":"يضحك"},{"w":"and","ar":"و"},{"w":"thanks","ar":"يشكر"},{"w":"him","ar":"ـه (هو)"},{"w":"three","ar":"ثلاثة"},{"w":"times","ar":"مرات"}]'::jsonb) on conflict do nothing;
insert into public.units (id, type, slug, title_en, title_ar, description_en, description_ar, level, theme, emoji, sort_order)
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('ef4ad68e-516f-5655-ab78-b082180f146f', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 0, 'Every summer, my family takes the bus to the sea.', 'كل صيف، تركب عائلتي الحافلة إلى البحر.', '[{"w":"Every","ar":"كل"},{"w":"summer","ar":"صيف"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"family","ar":"عائلة"},{"w":"takes","ar":"يركب / يأخذ"},{"w":"the","ar":"الـ"},{"w":"bus","ar":"الحافلة"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"the","ar":"الـ"},{"w":"sea","ar":"البحر"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('7d389518-b4ea-5690-a656-bdec9948fcb3', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 1, 'The trip is long, so we bring sandwiches and cold water.', 'الرحلة طويلة، لذلك نأخذ معنا شطائر وماءً بارداً.', '[{"w":"The","ar":"الـ"},{"w":"trip","ar":"الرحلة"},{"w":"is","ar":"يكون / هو"},{"w":"long","ar":"طويل"},{"w":"so","ar":"لذلك"},{"w":"we","ar":"نحن"},{"w":"bring","ar":"نحضر / نأخذ معنا"},{"w":"sandwiches","ar":"شطائر"},{"w":"and","ar":"و"},{"w":"cold","ar":"بارد"},{"w":"water","ar":"ماء"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('846ec9d4-8b2a-5922-a617-e24e58181188', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 2, 'My little brother always sits next to the window.', 'أخي الصغير يجلس دائماً بجانب النافذة.', '[{"w":"My","ar":"ـي (خاصتي)"},{"w":"little","ar":"صغير / قليلاً"},{"w":"brother","ar":"أخ"},{"w":"always","ar":"دائماً"},{"w":"sits","ar":"يجلس"},{"w":"next","ar":"بجانب (next to)"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"the","ar":"الـ"},{"w":"window","ar":"النافذة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('550199f8-ec7f-5bc1-89b4-716ae03f1751', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 3, 'He counts the trees and the cows on the way.', 'يعدّ الأشجار والأبقار في الطريق.', '[{"w":"He","ar":"هو"},{"w":"counts","ar":"يعدّ"},{"w":"the","ar":"الـ"},{"w":"trees","ar":"الأشجار"},{"w":"and","ar":"و"},{"w":"the","ar":"الـ"},{"w":"cows","ar":"الأبقار"},{"w":"on","ar":"على / في (الأيام)"},{"w":"the","ar":"الـ"},{"w":"way","ar":"الطريق"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('482da13b-1608-5cc1-9fb6-2b5835242528', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 4, 'After three hours, we can smell the salt in the air.', 'بعد ثلاث ساعات، نستطيع أن نشم رائحة الملح في الهواء.', '[{"w":"After","ar":"بعد"},{"w":"three","ar":"ثلاثة"},{"w":"hours","ar":"ساعات"},{"w":"we","ar":"نحن"},{"w":"can","ar":"يستطيع"},{"w":"smell","ar":"نشمّ"},{"w":"the","ar":"الـ"},{"w":"salt","ar":"الملح"},{"w":"in","ar":"في"},{"w":"the","ar":"الـ"},{"w":"air","ar":"الهواء"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('3de75987-d016-5d09-8d78-517fb6130aa8', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 5, 'The moment the doors open, he runs to the beach.', 'في اللحظة التي تُفتح فيها الأبواب، يركض إلى الشاطئ.', '[{"w":"The","ar":"الـ"},{"w":"moment","ar":"اللحظة"},{"w":"the","ar":"الـ"},{"w":"doors","ar":"الأبواب"},{"w":"open","ar":"تُفتح"},{"w":"he","ar":"هو"},{"w":"runs","ar":"يركض"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"the","ar":"الـ"},{"w":"beach","ar":"الشاطئ"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('ce794f3e-51fd-582c-8076-807a8dd5bcd5', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 6, 'My mother shouts at him to wait, but he never listens.', 'تصرخ أمي عليه لينتظر، لكنه لا يسمع الكلام أبداً.', '[{"w":"My","ar":"ـي (خاصتي)"},{"w":"mother","ar":"أمي"},{"w":"shouts","ar":"تصرخ"},{"w":"at","ar":"في / عند"},{"w":"him","ar":"ـه"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"wait","ar":"ينتظر"},{"w":"but","ar":"لكن"},{"w":"he","ar":"هو"},{"w":"never","ar":"أبداً"},{"w":"listens","ar":"يسمع الكلام"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('295fff14-709b-544b-adc0-5ca97b86d8b4', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 7, 'We spend the whole day swimming and building castles in the sand.', 'نقضي اليوم كله في السباحة وبناء القلاع في الرمل.', '[{"w":"We","ar":"نحن"},{"w":"spend","ar":"نقضي"},{"w":"the","ar":"الـ"},{"w":"whole","ar":"كامل / كله"},{"w":"day","ar":"يوم"},{"w":"swimming","ar":"السباحة"},{"w":"and","ar":"و"},{"w":"building","ar":"بناء"},{"w":"castles","ar":"قلاع"},{"w":"in","ar":"في"},{"w":"the","ar":"الـ"},{"w":"sand","ar":"الرمل"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('d67212cd-914f-5631-902d-554c1680907d', '7800197e-b9c6-56d5-82a4-53befab7a7ff', 8, 'On the way home, everyone falls asleep except the driver.', 'في طريق العودة، ينام الجميع ما عدا السائق.', '[{"w":"On","ar":"على / في (الأيام)"},{"w":"the","ar":"الـ"},{"w":"way","ar":"الطريق"},{"w":"home","ar":"البيت"},{"w":"everyone","ar":"الجميع"},{"w":"falls","ar":"يقع (falls asleep: يغفو)"},{"w":"asleep","ar":"نائم"},{"w":"except","ar":"ما عدا"},{"w":"the","ar":"الـ"},{"w":"driver","ar":"السائق"}]'::jsonb) on conflict do nothing;
insert into public.units (id, type, slug, title_en, title_ar, description_en, description_ar, level, theme, emoji, sort_order)
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('1f6e03a3-294f-5da4-9f5e-bf41f44a44e7', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 0, 'Lina was in the middle of an important exam.', 'كانت لينا في منتصف امتحان مهم.', '[{"w":"Lina","ar":"لينا"},{"w":"was","ar":"كان / كانت"},{"w":"in","ar":"في"},{"w":"the","ar":"الـ"},{"w":"middle","ar":"منتصف"},{"w":"of","ar":"من"},{"w":"an","ar":"ـًا / واحد"},{"w":"important","ar":"مهم"},{"w":"exam","ar":"امتحان"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('55f95694-6f63-52cd-95f0-ca2977ce70b8', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 1, 'The room was silent, and everyone was writing.', 'كانت القاعة صامتة، والجميع يكتبون.', '[{"w":"The","ar":"الـ"},{"w":"room","ar":"غرفة / قاعة"},{"w":"was","ar":"كان / كانت"},{"w":"silent","ar":"صامت"},{"w":"and","ar":"و"},{"w":"everyone","ar":"الجميع"},{"w":"was","ar":"كان / كانت"},{"w":"writing","ar":"يكتبون / كتابة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('4499b66a-4d65-5c32-ab57-c3b536f27bbd', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 2, 'Suddenly, a loud song started playing from her bag.', 'فجأة، بدأت أغنية عالية تعمل من حقيبتها.', '[{"w":"Suddenly","ar":"فجأة"},{"w":"a","ar":"ـًا / واحد"},{"w":"loud","ar":"عالٍ"},{"w":"song","ar":"أغنية"},{"w":"started","ar":"بدأت"},{"w":"playing","ar":"يعمل / يُشغَّل"},{"w":"from","ar":"من"},{"w":"her","ar":"ها / لها"},{"w":"bag","ar":"حقيبة / كيس"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('3ea92811-e812-5435-8705-d2cccba454ca', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 3, 'Her face turned red as every head turned toward her.', 'احمرّ وجهها عندما التفتت كل الرؤوس نحوها.', '[{"w":"Her","ar":"ها / لها"},{"w":"face","ar":"وجه"},{"w":"turned","ar":"تحوّل / التفت"},{"w":"red","ar":"أحمر"},{"w":"as","ar":"عندما"},{"w":"every","ar":"كل"},{"w":"head","ar":"رأس"},{"w":"turned","ar":"تحوّل / التفت"},{"w":"toward","ar":"نحو"},{"w":"her","ar":"ها / لها"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('ccf3ff88-cf52-54fa-a4a8-f3902ab9fc21', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 4, 'She had forgotten to turn off her alarm.', 'كانت قد نسيت أن تطفئ المنبّه.', '[{"w":"She","ar":"هي"},{"w":"had","ar":"كان قد / كان عندي"},{"w":"forgotten","ar":"نسيت"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"turn","ar":"(turn off: يطفئ)"},{"w":"off","ar":"(turn off: يطفئ)"},{"w":"her","ar":"ها / لها"},{"w":"alarm","ar":"منبّه"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('f6d0ec26-2e8a-5cb2-9965-ee0dcfacf9cb', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 5, 'She searched for the phone with shaking hands.', 'بحثت عن الهاتف بيدين مرتجفتين.', '[{"w":"She","ar":"هي"},{"w":"searched","ar":"بحثت"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"the","ar":"الـ"},{"w":"phone","ar":"الهاتف"},{"w":"with","ar":"مع / بـ"},{"w":"shaking","ar":"مرتجفة"},{"w":"hands","ar":"يدين"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('707ed680-a352-5710-aa4b-c24bbb047f41', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 6, 'The teacher walked over slowly and raised one eyebrow.', 'مشى المعلم نحوها ببطء ورفع حاجباً واحداً.', '[{"w":"The","ar":"الـ"},{"w":"teacher","ar":"المعلم"},{"w":"walked","ar":"مشى / دخل"},{"w":"over","ar":"نحو / إلى هناك"},{"w":"slowly","ar":"ببطء"},{"w":"and","ar":"و"},{"w":"raised","ar":"رفع"},{"w":"one","ar":"واحد"},{"w":"eyebrow","ar":"حاجب"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('3af69371-acc8-578c-ae2a-2473436e7bc8', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 7, '"Nice song," he said, "but please finish your exam first."', 'قال: "أغنية جميلة، لكن من فضلك أنهي امتحانك أولاً."', '[{"w":"Nice","ar":"جميل / لطيف"},{"w":"song","ar":"أغنية"},{"w":"he","ar":"هو"},{"w":"said","ar":"قال / قالت"},{"w":"but","ar":"لكن"},{"w":"please","ar":"من فضلك"},{"w":"finish","ar":"أنهِ"},{"w":"your","ar":"ـك (خاصتك)"},{"w":"exam","ar":"امتحان"},{"w":"first","ar":"أول / أولاً"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('a1fc73b2-7a62-5354-8da1-614e5f673a9d', '1372c4a4-3e7a-5e3d-8db0-e9fad733afe5', 8, 'The whole class laughed, and Lina finally relaxed.', 'ضحك الفصل كله، وأخيراً ارتاحت لينا.', '[{"w":"The","ar":"الـ"},{"w":"whole","ar":"كامل / كله"},{"w":"class","ar":"صف / فصل"},{"w":"laughed","ar":"ضحك"},{"w":"and","ar":"و"},{"w":"Lina","ar":"لينا"},{"w":"finally","ar":"أخيراً"},{"w":"relaxed","ar":"ارتاحت"}]'::jsonb) on conflict do nothing;
insert into public.units (id, type, slug, title_en, title_ar, description_en, description_ar, level, theme, emoji, sort_order)
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('6aa49d21-9855-52e3-9f48-9755312fa101', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 0, 'My grandmother never wrote her recipes down.', 'جدتي لم تكتب وصفاتها أبداً.', '[{"w":"My","ar":"ـي (خاصتي)"},{"w":"grandmother","ar":"جدتي"},{"w":"never","ar":"أبداً"},{"w":"wrote","ar":"كتبت (wrote down: دوّنت)"},{"w":"her","ar":"ها / لها"},{"w":"recipes","ar":"وصفات"},{"w":"down","ar":"(wrote down: دوّن)"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('63c09a1c-ec74-58cf-888f-423cbe30fc22', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 1, 'She cooked from memory, adding a little of this and a little of that.', 'كانت تطبخ من ذاكرتها، تضيف قليلاً من هذا وقليلاً من ذاك.', '[{"w":"She","ar":"هي"},{"w":"cooked","ar":"طبخت"},{"w":"from","ar":"من"},{"w":"memory","ar":"الذاكرة"},{"w":"adding","ar":"تضيف"},{"w":"a","ar":"ـًا / واحد"},{"w":"little","ar":"صغير / قليلاً"},{"w":"of","ar":"من"},{"w":"this","ar":"هذا"},{"w":"and","ar":"و"},{"w":"a","ar":"ـًا / واحد"},{"w":"little","ar":"صغير / قليلاً"},{"w":"of","ar":"من"},{"w":"that","ar":"ذلك / أنّ"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('af2d37b0-67f1-5034-ae51-406b2df4df21', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 2, 'When I asked her how much salt to use, she just shrugged.', 'عندما سألتها كم من الملح أستخدم، هزّت كتفيها فقط.', '[{"w":"When","ar":"عندما / متى"},{"w":"I","ar":"أنا"},{"w":"asked","ar":"سألت"},{"w":"her","ar":"ها / لها"},{"w":"how","ar":"كيف / كم"},{"w":"much","ar":"كم / كثير"},{"w":"salt","ar":"الملح"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"use","ar":"يستخدم"},{"w":"she","ar":"هي"},{"w":"just","ar":"فقط"},{"w":"shrugged","ar":"هزّت كتفيها"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('63fc0946-ee82-5b20-9413-d3afcb30a213', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 3, '"Enough," she said, as if that explained everything.', 'قالت: "ما يكفي"، كأن ذلك يشرح كل شيء.', '[{"w":"Enough","ar":"يكفي / كفاية"},{"w":"she","ar":"هي"},{"w":"said","ar":"قال / قالت"},{"w":"as","ar":"كأن (as if)"},{"w":"if","ar":"لو (as if: كأن)"},{"w":"that","ar":"ذلك / أنّ"},{"w":"explained","ar":"شرح"},{"w":"everything","ar":"كل شيء"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('7bd6d971-71af-5f0b-b364-c5d86b35a81b', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 4, 'Last winter, I decided to learn her famous lentil soup.', 'في الشتاء الماضي، قررت أن أتعلم شوربة العدس المشهورة التي تصنعها.', '[{"w":"Last","ar":"الماضي"},{"w":"winter","ar":"الشتاء"},{"w":"I","ar":"أنا"},{"w":"decided","ar":"قررت"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"learn","ar":"أتعلم"},{"w":"her","ar":"ها / لها"},{"w":"famous","ar":"مشهور"},{"w":"lentil","ar":"عدس"},{"w":"soup","ar":"شوربة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('9114f5e2-839f-5ddf-a98a-1374addc6605', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 5, 'I stood next to her in the kitchen and took notes on my phone.', 'وقفت بجانبها في المطبخ وكتبت ملاحظات على هاتفي.', '[{"w":"I","ar":"أنا"},{"w":"stood","ar":"وقف / وقفت"},{"w":"next","ar":"بجانب (next to)"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"her","ar":"ها / لها"},{"w":"in","ar":"في"},{"w":"the","ar":"الـ"},{"w":"kitchen","ar":"المطبخ"},{"w":"and","ar":"و"},{"w":"took","ar":"أخذ / كتبت"},{"w":"notes","ar":"ملاحظات"},{"w":"on","ar":"على / في (الأيام)"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"phone","ar":"الهاتف"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('83efd82c-6f9e-54be-bd93-5d7c57323e2a', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 6, 'My first try tasted nothing like hers.', 'محاولتي الأولى لم يكن طعمها يشبه طعم شوربتها أبداً.', '[{"w":"My","ar":"ـي (خاصتي)"},{"w":"first","ar":"أول / أولاً"},{"w":"try","ar":"محاولة"},{"w":"tasted","ar":"تذوّقت / كان طعمه"},{"w":"nothing","ar":"لا شيء"},{"w":"like","ar":"مثل"},{"w":"hers","ar":"خاصتها"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('292ec381-e095-58e6-a9a3-ba0451a1ca23', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 7, 'She tasted it, smiled, and added a squeeze of lemon.', 'تذوقتها، وابتسمت، وأضافت عصرة ليمون.', '[{"w":"She","ar":"هي"},{"w":"tasted","ar":"تذوّقت / كان طعمه"},{"w":"it","ar":"ها (الشوربة)"},{"w":"smiled","ar":"ابتسمت"},{"w":"and","ar":"و"},{"w":"added","ar":"أضاف"},{"w":"a","ar":"ـًا / واحد"},{"w":"squeeze","ar":"عصرة"},{"w":"of","ar":"من"},{"w":"lemon","ar":"ليمون"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('03e83bfc-2d74-503a-8180-55b5acb48c4d', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 8, 'Suddenly, it tasted exactly like my childhood.', 'فجأة، صار طعمها تماماً مثل طفولتي.', '[{"w":"Suddenly","ar":"فجأة"},{"w":"it","ar":"ها (الشوربة)"},{"w":"tasted","ar":"تذوّقت / كان طعمه"},{"w":"exactly","ar":"تماماً"},{"w":"like","ar":"مثل"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"childhood","ar":"الطفولة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('427d2b21-7e33-5200-a82c-29bf30ffc31b', '2c8bdcab-12c0-50e0-b5aa-95f18a247300', 9, 'Now the recipe lives in my phone, but the secret is still in her hands.', 'الآن الوصفة محفوظة في هاتفي، لكن السر ما زال في يديها.', '[{"w":"Now","ar":"الآن"},{"w":"the","ar":"الـ"},{"w":"recipe","ar":"الوصفة"},{"w":"lives","ar":"يسكن / تعيش"},{"w":"in","ar":"في"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"phone","ar":"الهاتف"},{"w":"but","ar":"لكن"},{"w":"the","ar":"الـ"},{"w":"secret","ar":"السر"},{"w":"is","ar":"يكون / هو"},{"w":"still","ar":"ما زال"},{"w":"in","ar":"في"},{"w":"her","ar":"ها / لها"},{"w":"hands","ar":"يدين"}]'::jsonb) on conflict do nothing;
insert into public.units (id, type, slug, title_en, title_ar, description_en, description_ar, level, theme, emoji, sort_order)
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('a4889f06-d998-5fc7-8f26-eedcbd4b600a', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 0, 'Khalid arrived at the office twenty minutes early.', 'وصل خالد إلى المكتب قبل الموعد بعشرين دقيقة.', '[{"w":"Khalid","ar":"خالد"},{"w":"arrived","ar":"وصل"},{"w":"at","ar":"في / عند"},{"w":"the","ar":"الـ"},{"w":"office","ar":"المكتب"},{"w":"twenty","ar":"عشرون"},{"w":"minutes","ar":"دقائق"},{"w":"early","ar":"مبكراً"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('3209640a-d0fa-531d-95b7-62d5b55c6af6', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 1, 'He had practiced his answers in front of the mirror all week.', 'كان قد تدرّب على إجاباته أمام المرآة طوال الأسبوع.', '[{"w":"He","ar":"هو"},{"w":"had","ar":"كان قد / كان عندي"},{"w":"practiced","ar":"تدرّب"},{"w":"his","ar":"ـه (له)"},{"w":"answers","ar":"إجابات"},{"w":"in","ar":"في"},{"w":"front","ar":"أمام (in front of)"},{"w":"of","ar":"من"},{"w":"the","ar":"الـ"},{"w":"mirror","ar":"المرآة"},{"w":"all","ar":"كل / طوال"},{"w":"week","ar":"أسبوع"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('5c13455a-8708-574c-90cd-7a75b4d40415', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 2, 'While he was waiting, he noticed a woman struggling with a heavy box.', 'بينما كان ينتظر، لاحظ امرأة تجد صعوبة في حمل صندوق ثقيل.', '[{"w":"While","ar":"بينما"},{"w":"he","ar":"هو"},{"w":"was","ar":"كان / كانت"},{"w":"waiting","ar":"ينتظر"},{"w":"he","ar":"هو"},{"w":"noticed","ar":"لاحظ"},{"w":"a","ar":"ـًا / واحد"},{"w":"woman","ar":"امرأة"},{"w":"struggling","ar":"تجد صعوبة"},{"w":"with","ar":"مع / بـ"},{"w":"a","ar":"ـًا / واحد"},{"w":"heavy","ar":"ثقيل"},{"w":"box","ar":"صندوق"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('81d3eead-72cf-5ceb-a179-2b1d8ab754af', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 3, 'Without thinking, he stood up and helped her carry it to the elevator.', 'دون تفكير، وقف وساعدها في حمله إلى المصعد.', '[{"w":"Without","ar":"بدون"},{"w":"thinking","ar":"التفكير"},{"w":"he","ar":"هو"},{"w":"stood","ar":"وقف / وقفت"},{"w":"up","ar":"(wake up: يستيقظ)"},{"w":"and","ar":"و"},{"w":"helped","ar":"ساعد"},{"w":"her","ar":"ها"},{"w":"carry","ar":"يحمل"},{"w":"it","ar":"ـه (الصندوق)"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"the","ar":"الـ"},{"w":"elevator","ar":"المصعد"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('d7b5ae0a-6880-573d-81ef-3ea2eb67ce9c', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 4, 'She thanked him and disappeared behind the closing doors.', 'شكرته واختفت خلف الأبواب التي تُغلق.', '[{"w":"She","ar":"هي"},{"w":"thanked","ar":"شكرت"},{"w":"him","ar":"ـه (هو)"},{"w":"and","ar":"و"},{"w":"disappeared","ar":"اختفت"},{"w":"behind","ar":"خلف"},{"w":"the","ar":"الـ"},{"w":"closing","ar":"التي تُغلق"},{"w":"doors","ar":"الأبواب"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('b06b5599-103b-54c2-aea3-349150dddb2f', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 5, 'A few minutes later, his name was called.', 'بعد دقائق قليلة، نُودي اسمه.', '[{"w":"A","ar":"ـًا / واحد"},{"w":"few","ar":"قليل (a few: بضعة)"},{"w":"minutes","ar":"دقائق"},{"w":"later","ar":"لاحقاً / بعد"},{"w":"his","ar":"ـه (له)"},{"w":"name","ar":"اسم"},{"w":"was","ar":"كان / كانت"},{"w":"called","ar":"نُودي"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('1db2e93c-e595-5313-9054-2427b2070bd2', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 6, 'He walked into the meeting room and froze.', 'دخل إلى غرفة الاجتماعات وتجمّد في مكانه.', '[{"w":"He","ar":"هو"},{"w":"walked","ar":"مشى / دخل"},{"w":"into","ar":"إلى (داخل)"},{"w":"the","ar":"الـ"},{"w":"meeting","ar":"الاجتماعات"},{"w":"room","ar":"غرفة / قاعة"},{"w":"and","ar":"و"},{"w":"froze","ar":"تجمّد"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('634e8ab7-c985-5ba2-9ebe-a560c2fa2756', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 7, 'The woman with the box was sitting at the head of the table.', 'المرأة صاحبة الصندوق كانت تجلس على رأس الطاولة.', '[{"w":"The","ar":"الـ"},{"w":"woman","ar":"امرأة"},{"w":"with","ar":"مع / بـ"},{"w":"the","ar":"الـ"},{"w":"box","ar":"صندوق"},{"w":"was","ar":"كان / كانت"},{"w":"sitting","ar":"تجلس"},{"w":"at","ar":"في / عند"},{"w":"the","ar":"الـ"},{"w":"head","ar":"رأس"},{"w":"of","ar":"من"},{"w":"the","ar":"الـ"},{"w":"table","ar":"الطاولة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('c46ce208-cc8a-58aa-aedf-33e0b078f68f', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 8, '"You already answered my most important question," she said with a smile.', 'قالت بابتسامة: "لقد أجبت عن أهم سؤال عندي."', '[{"w":"You","ar":"أنت"},{"w":"already","ar":"بالفعل / سابقاً"},{"w":"answered","ar":"أجبت"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"most","ar":"معظم / أكثر"},{"w":"important","ar":"مهم"},{"w":"question","ar":"سؤال"},{"w":"she","ar":"هي"},{"w":"said","ar":"قال / قالت"},{"w":"with","ar":"مع / بـ"},{"w":"a","ar":"ـًا / واحد"},{"w":"smile","ar":"ابتسامة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('038277ef-400f-5c3f-b099-acf5ffe413df', '73058a5d-f3ef-53d8-a097-e89cf8fd763a', 9, 'He got the job before he had even opened his folder.', 'حصل على الوظيفة قبل أن يفتح ملفه حتى.', '[{"w":"He","ar":"هو"},{"w":"got","ar":"حصل على"},{"w":"the","ar":"الـ"},{"w":"job","ar":"الوظيفة"},{"w":"before","ar":"قبل"},{"w":"he","ar":"هو"},{"w":"had","ar":"كان قد / كان عندي"},{"w":"even","ar":"حتى"},{"w":"opened","ar":"فتح"},{"w":"his","ar":"ـه (له)"},{"w":"folder","ar":"ملف"}]'::jsonb) on conflict do nothing;
