insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('bb2eb4bf-3475-5281-99b5-228bb7a35541', 'be518150-e595-5fc8-ba24-ad57510aea04', 1, 'They have two young children and a very loud parrot.', 'عندهم طفلان صغيران وببغاء صوته عالٍ جداً.', '[{"w":"They","ar":"هم"},{"w":"have","ar":"عندهم / يملكون"},{"w":"two","ar":"اثنان"},{"w":"young","ar":"صغار"},{"w":"children","ar":"أطفال"},{"w":"and","ar":"و"},{"w":"a","ar":"ـًا / واحد"},{"w":"very","ar":"جداً"},{"w":"loud","ar":"عالٍ"},{"w":"parrot","ar":"ببغاء"}]'::jsonb) on conflict do nothing;
