insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('8643e4d9-2d38-5bc0-b708-e9b2d20d0c0b', 'fd5750bc-682d-55b2-96f3-632cd35ad2e9', 1, 'As a child, I was always afraid of deep water.', 'عندما كنت طفلاً، كنت دائماً أخاف من الماء العميق.', '[{"w":"As","ar":"عندما (as a child: في طفولتي)"},{"w":"a","ar":"ـًا / واحد"},{"w":"child","ar":"طفل"},{"w":"I","ar":"أنا"},{"w":"was","ar":"كان / كانت"},{"w":"always","ar":"دائماً"},{"w":"afraid","ar":"خائف"},{"w":"of","ar":"من"},{"w":"deep","ar":"عميق"},{"w":"water","ar":"ماء"}]'::jsonb) on conflict do nothing;
