insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('b1143238-a690-51c5-9dd3-8d4ae7eb9132', 'fd5750bc-682d-55b2-96f3-632cd35ad2e9', 3, 'Most of the other students were also nervous beginners.', 'معظم الطلاب الآخرين كانوا أيضاً مبتدئين متوترين.', '[{"w":"Most","ar":"معظم / أكثر"},{"w":"of","ar":"من"},{"w":"the","ar":"الـ"},{"w":"other","ar":"الآخر / الأخرى"},{"w":"students","ar":"الطلاب"},{"w":"were","ar":"كانوا"},{"w":"also","ar":"أيضاً"},{"w":"nervous","ar":"متوترون"},{"w":"beginners","ar":"مبتدئون"}]'::jsonb) on conflict do nothing;
