insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('e5a2e851-f940-5e07-bfae-57a1c1cfaceb', 'fd5750bc-682d-55b2-96f3-632cd35ad2e9', 0, 'How old was the speaker when they learned to swim?', 'كم كان عمر المتحدث عندما تعلّم السباحة؟', '["Ten","Fifteen","Twenty-five","Thirty"]'::jsonb, 2) on conflict do nothing;
