insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('0a4f30c8-2d12-58cf-b3fd-6646727ce070', 'df98879b-e5fb-59d9-92c8-5b24fb2a34dd', 1, 'With a card, you can borrow up to six books at a time.', 'بالبطاقة، تستطيع أن تستعير حتى ستة كتب في المرة الواحدة.', '[{"w":"With","ar":"مع / بـ"},{"w":"a","ar":"ـًا / واحد"},{"w":"card","ar":"بطاقة"},{"w":"you","ar":"أنت"},{"w":"can","ar":"يستطيع"},{"w":"borrow","ar":"تستعير"},{"w":"up","ar":"(up to: حتى)"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"six","ar":"ستة"},{"w":"books","ar":"كتب"},{"w":"at","ar":"في / عند"},{"w":"a","ar":"ـًا / واحد"},{"w":"time","ar":"مرة (at a time: في المرة الواحدة)"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('5a17f80f-9b94-5875-b2ef-afe1d4df78e4', 'df98879b-e5fb-59d9-92c8-5b24fb2a34dd', 2, 'You can keep them for three weeks.', 'تستطيع أن تحتفظ بها ثلاثة أسابيع.', '[{"w":"You","ar":"أنت"},{"w":"can","ar":"يستطيع"},{"w":"keep","ar":"تحتفظ"},{"w":"them","ar":"ها (الكتب)"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"three","ar":"ثلاثة"},{"w":"weeks","ar":"أسابيع"}]'::jsonb) on conflict do nothing;
