insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('d5211570-dc89-59c1-997b-46575466d52b', 'df98879b-e5fb-59d9-92c8-5b24fb2a34dd', 4, 'The library also has quiet rooms where students can study for free.', 'في المكتبة أيضاً غرف هادئة يستطيع الطلاب أن يذاكروا فيها مجاناً.', '[{"w":"The","ar":"الـ"},{"w":"library","ar":"المكتبة"},{"w":"also","ar":"أيضاً"},{"w":"has","ar":"يملك / فيه"},{"w":"quiet","ar":"هادئ"},{"w":"rooms","ar":"غرف"},{"w":"where","ar":"حيث"},{"w":"students","ar":"الطلاب"},{"w":"can","ar":"يستطيع"},{"w":"study","ar":"يذاكرون"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"free","ar":"مجاناً"}]'::jsonb) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('47d931a6-d331-5272-b783-2f8645d81fd5', 'df98879b-e5fb-59d9-92c8-5b24fb2a34dd', 0, 'How much does a library card cost?', 'كم تكلفة بطاقة المكتبة؟', '["It is free","Six dollars","Three dollars","It depends"]'::jsonb, 0) on conflict do nothing;
