insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('2be1f81d-2a1e-5697-ad82-bb93f3ddaadd', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 0, 'Since the company changed its rules, I work from home three days a week.', 'منذ أن غيّرت الشركة قوانينها، أعمل من البيت ثلاثة أيام في الأسبوع.', '[{"w":"Since","ar":"منذ"},{"w":"the","ar":"الـ"},{"w":"company","ar":"الشركة"},{"w":"changed","ar":"غيّرت"},{"w":"its","ar":"ـها (الخاصة بها)"},{"w":"rules","ar":"قوانين"},{"w":"I","ar":"أنا"},{"w":"work","ar":"العمل / أعمل"},{"w":"from","ar":"من"},{"w":"home","ar":"البيت"},{"w":"three","ar":"ثلاثة"},{"w":"days","ar":"أيام"},{"w":"a","ar":"ـًا / واحد"},{"w":"week","ar":"أسبوع"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('e8dc0ac6-ce47-5423-8f63-0071540872bf', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 1, 'I save almost two hours that I used to spend in traffic.', 'أوفّر تقريباً ساعتين كنت أقضيهما في الزحام.', '[{"w":"I","ar":"أنا"},{"w":"save","ar":"أوفّر"},{"w":"almost","ar":"تقريباً"},{"w":"two","ar":"اثنان"},{"w":"hours","ar":"ساعات"},{"w":"that","ar":"ذلك / أنّ"},{"w":"I","ar":"أنا"},{"w":"used","ar":"(used to: كنت ...)"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"spend","ar":"نقضي"},{"w":"in","ar":"في"},{"w":"traffic","ar":"الزحام"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('2acb5caf-dd84-53ba-812f-0cc68f1c9487', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 2, 'However, it can be hard to stop working when the office is in your living room.', 'لكن قد يكون من الصعب أن تتوقف عن العمل عندما يكون المكتب في غرفة الجلوس.', '[{"w":"However","ar":"لكن / ومع ذلك"},{"w":"it","ar":"هو / هي"},{"w":"can","ar":"يستطيع"},{"w":"be","ar":"يكون"},{"w":"hard","ar":"صعب"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"stop","ar":"يتوقف"},{"w":"working","ar":"العمل"},{"w":"when","ar":"عندما / متى"},{"w":"the","ar":"الـ"},{"w":"office","ar":"المكتب"},{"w":"is","ar":"يكون / هو"},{"w":"in","ar":"في"},{"w":"your","ar":"ـك (خاصتك)"},{"w":"living","ar":"(living room: غرفة الجلوس)"},{"w":"room","ar":"غرفة / قاعة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('69cd052a-3017-5afd-9198-531150d9d0ce', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 3, 'To fix this, I close my laptop at six o''clock and go for a walk.', 'لأحل هذه المشكلة، أغلق حاسوبي الساعة السادسة وأخرج للمشي.', '[{"w":"To","ar":"إلى / لـ / أن"},{"w":"fix","ar":"أصلح / أحلّ"},{"w":"this","ar":"هذا (هذه المشكلة)"},{"w":"I","ar":"أنا"},{"w":"close","ar":"أغلق"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"laptop","ar":"حاسوب محمول"},{"w":"at","ar":"في / عند"},{"w":"six","ar":"ستة"},{"w":"o''clock","ar":"الساعة (بالضبط)"},{"w":"and","ar":"و"},{"w":"go","ar":"أذهب (go for a walk: أتمشّى)"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"a","ar":"ـًا / واحد"},{"w":"walk","ar":"أمشي / مشي"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('ec12898c-88ca-51e8-91a0-6b9be2830056', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 4, 'That short walk is how my brain knows the workday is over.', 'ذلك المشي القصير هو الطريقة التي يعرف بها عقلي أن يوم العمل انتهى.', '[{"w":"That","ar":"ذلك / أنّ"},{"w":"short","ar":"قصير"},{"w":"walk","ar":"أمشي / مشي"},{"w":"is","ar":"يكون / هو"},{"w":"how","ar":"كيف / كم"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"brain","ar":"العقل / الدماغ"},{"w":"knows","ar":"يعرف"},{"w":"the","ar":"الـ"},{"w":"workday","ar":"يوم العمل"},{"w":"is","ar":"يكون / هو"},{"w":"over","ar":"انتهى"}]'::jsonb) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('1f56fff1-fbd3-5445-8063-1cfcc4473fda', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 0, 'How many days a week does the speaker work from home?', 'كم يوماً في الأسبوع يعمل المتحدث من البيت؟', '["Two","Three","Four","Five"]'::jsonb, 1) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('8e8c388a-e405-505a-9c8f-00b8d0f4a63a', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 1, 'What is the main difficulty of working from home?', 'ما الصعوبة الرئيسية في العمل من البيت؟', '["Slow internet","Stopping work at the end of the day","Noisy neighbors","Not enough space"]'::jsonb, 1) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('30c805b6-e498-5fb9-880f-d22f056e92bd', '9abe8ef2-9ff0-5cb5-9ebc-1bc091e09186', 2, 'Why does the speaker go for a walk at six?', 'لماذا يتمشّى المتحدث الساعة السادسة؟', '["To buy dinner","To train for a race","To mark the end of the workday","To meet a friend"]'::jsonb, 2) on conflict do nothing;
