insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('868db8af-5b61-5008-b8d1-bcadcd5f969e', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 0, 'Last month, I spent a weekend in the mountains without my phone.', 'الشهر الماضي، قضيت عطلة نهاية الأسبوع في الجبال بدون هاتفي.', '[{"w":"Last","ar":"الماضي"},{"w":"month","ar":"شهر"},{"w":"I","ar":"أنا"},{"w":"spent","ar":"قضيت"},{"w":"a","ar":"ـًا / واحد"},{"w":"weekend","ar":"عطلة نهاية الأسبوع"},{"w":"in","ar":"في"},{"w":"the","ar":"الـ"},{"w":"mountains","ar":"الجبال"},{"w":"without","ar":"بدون"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"phone","ar":"الهاتف"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('3e897c18-5495-5e90-8b0c-3499a76f6180', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 1, 'For the first few hours, I kept reaching for my pocket out of habit.', 'في الساعات الأولى، ظللت أمد يدي إلى جيبي من باب العادة.', '[{"w":"For","ar":"لـ / من أجل / لمدة"},{"w":"the","ar":"الـ"},{"w":"first","ar":"أول / أولاً"},{"w":"few","ar":"قليل (a few: بضعة)"},{"w":"hours","ar":"ساعات"},{"w":"I","ar":"أنا"},{"w":"kept","ar":"ظلّ / استمر"},{"w":"reaching","ar":"أمدّ يدي"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"pocket","ar":"جيب"},{"w":"out","ar":"(out of habit: بحكم العادة)"},{"w":"of","ar":"من"},{"w":"habit","ar":"عادة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('087a0220-b129-5a07-92da-1429a7991263', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 2, 'By the evening, I had stopped thinking about messages and news.', 'بحلول المساء، كنت قد توقفت عن التفكير في الرسائل والأخبار.', '[{"w":"By","ar":"بحلول / بـ"},{"w":"the","ar":"الـ"},{"w":"evening","ar":"المساء"},{"w":"I","ar":"أنا"},{"w":"had","ar":"كان قد / كان عندي"},{"w":"stopped","ar":"توقفت"},{"w":"thinking","ar":"التفكير"},{"w":"about","ar":"عن"},{"w":"messages","ar":"الرسائل"},{"w":"and","ar":"و"},{"w":"news","ar":"الأخبار"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('0afa5822-770e-594f-9bfc-9547e8f3f30d', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 3, 'I noticed sounds I usually ignore, like the wind in the trees and the birds at sunrise.', 'لاحظت أصواتاً أتجاهلها عادة، مثل الريح في الأشجار والطيور عند الشروق.', '[{"w":"I","ar":"أنا"},{"w":"noticed","ar":"لاحظ"},{"w":"sounds","ar":"أصوات"},{"w":"I","ar":"أنا"},{"w":"usually","ar":"عادةً"},{"w":"ignore","ar":"أتجاهل"},{"w":"like","ar":"مثل"},{"w":"the","ar":"الـ"},{"w":"wind","ar":"الريح"},{"w":"in","ar":"في"},{"w":"the","ar":"الـ"},{"w":"trees","ar":"الأشجار"},{"w":"and","ar":"و"},{"w":"the","ar":"الـ"},{"w":"birds","ar":"الطيور"},{"w":"at","ar":"في / عند"},{"w":"sunrise","ar":"الشروق"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('e2e5ab89-bfaa-5885-a548-765944c02179', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 4, 'When I came back, I had dozens of notifications, but none of them were urgent.', 'عندما عدت، كانت عندي عشرات الإشعارات، لكن لم يكن أي منها عاجلاً.', '[{"w":"When","ar":"عندما / متى"},{"w":"I","ar":"أنا"},{"w":"came","ar":"جاء (came back: عاد)"},{"w":"back","ar":"عائداً (come back: يعود)"},{"w":"I","ar":"أنا"},{"w":"had","ar":"كان قد / كان عندي"},{"w":"dozens","ar":"عشرات"},{"w":"of","ar":"من"},{"w":"notifications","ar":"إشعارات"},{"w":"but","ar":"لكن"},{"w":"none","ar":"لا أحد / لا شيء"},{"w":"of","ar":"من"},{"w":"them","ar":"ها (الإشعارات)"},{"w":"were","ar":"كانوا"},{"w":"urgent","ar":"عاجل"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('8ca7128e-5a6f-5bfd-992f-2071de875cc3', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 5, 'Now I leave my phone in another room for one hour every evening.', 'الآن أترك هاتفي في غرفة أخرى ساعة واحدة كل مساء.', '[{"w":"Now","ar":"الآن"},{"w":"I","ar":"أنا"},{"w":"leave","ar":"أترك"},{"w":"my","ar":"ـي (خاصتي)"},{"w":"phone","ar":"الهاتف"},{"w":"in","ar":"في"},{"w":"another","ar":"آخر / أخرى"},{"w":"room","ar":"غرفة / قاعة"},{"w":"for","ar":"لـ / من أجل / لمدة"},{"w":"one","ar":"واحد"},{"w":"hour","ar":"ساعة"},{"w":"every","ar":"كل"},{"w":"evening","ar":"المساء"}]'::jsonb) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('61ddb958-2055-5837-b6c4-623c59a26bd9', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 0, 'Where did the speaker spend the weekend?', 'أين قضى المتحدث عطلة نهاية الأسبوع؟', '["At the beach","In the mountains","In a big city","At home"]'::jsonb, 1) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('5049431f-dfa8-5c26-b1de-c5ae3817c656', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 1, 'What happened in the first few hours?', 'ماذا حدث في الساعات الأولى؟', '["The speaker felt calm","The speaker kept reaching for the phone","The speaker got lost","The speaker fell asleep"]'::jsonb, 1) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('4a0a7d31-d14b-5ad3-9986-fd01364041f5', 'b0d87a8a-0fdd-545a-870d-8b00da4f920a', 2, 'What new habit does the speaker have?', 'ما العادة الجديدة عند المتحدث؟', '["Hiking every weekend","Turning off notifications forever","Leaving the phone in another room each evening","Waking up at sunrise"]'::jsonb, 2) on conflict do nothing;
insert into public.units (id, type, slug, title_en, title_ar, description_en, description_ar, level, theme, emoji, sort_order)
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('27dde537-2954-56af-a569-4c42d12bd563', '460577a1-3785-5fec-b406-ddbd8933f059', 0, 'Most people forget a new word within a few days if they never use it again.', 'معظم الناس ينسون الكلمة الجديدة خلال أيام قليلة إذا لم يستخدموها مرة أخرى.', '[{"w":"Most","ar":"معظم / أكثر"},{"w":"people","ar":"الناس"},{"w":"forget","ar":"ينسون"},{"w":"a","ar":"ـًا / واحد"},{"w":"new","ar":"جديد"},{"w":"word","ar":"كلمة"},{"w":"within","ar":"خلال"},{"w":"a","ar":"ـًا / واحد"},{"w":"few","ar":"قليل (a few: بضعة)"},{"w":"days","ar":"أيام"},{"w":"if","ar":"إذا"},{"w":"they","ar":"هم"},{"w":"never","ar":"أبداً"},{"w":"use","ar":"يستخدم"},{"w":"it","ar":"ها (الكلمة)"},{"w":"again","ar":"مرة أخرى"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('c4d95f03-b00e-5839-93c9-fbe9a1bc9cec', '460577a1-3785-5fec-b406-ddbd8933f059', 1, 'Scientists call this the forgetting curve.', 'يسمي العلماء هذا «منحنى النسيان».', '[{"w":"Scientists","ar":"العلماء"},{"w":"call","ar":"يسمّون"},{"w":"this","ar":"هذا"},{"w":"the","ar":"الـ"},{"w":"forgetting","ar":"النسيان"},{"w":"curve","ar":"منحنى"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('faf8197d-6efd-5f5a-9347-fd0ac5504be8', '460577a1-3785-5fec-b406-ddbd8933f059', 2, 'The good news is that each review makes the memory stronger and slower to fade.', 'الخبر الجيد أن كل مراجعة تجعل الذاكرة أقوى وأبطأ في التلاشي.', '[{"w":"The","ar":"الـ"},{"w":"good","ar":"جيد"},{"w":"news","ar":"الخبر"},{"w":"is","ar":"يكون / هو"},{"w":"that","ar":"ذلك / أنّ"},{"w":"each","ar":"كل"},{"w":"review","ar":"مراجعة"},{"w":"makes","ar":"يجعل"},{"w":"the","ar":"الـ"},{"w":"memory","ar":"الذاكرة"},{"w":"stronger","ar":"أقوى"},{"w":"and","ar":"و"},{"w":"slower","ar":"أبطأ"},{"w":"to","ar":"إلى / لـ / أن"},{"w":"fade","ar":"يتلاشى"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('b07e36e2-fc1e-5469-8619-f9d2f848cb32', '460577a1-3785-5fec-b406-ddbd8933f059', 3, 'Reviewing a word after one day, then after a week, then after a month works much better than studying it ten times in one night.', 'مراجعة الكلمة بعد يوم، ثم بعد أسبوع، ثم بعد شهر تنجح أكثر بكثير من مذاكرتها عشر مرات في ليلة واحدة.', '[{"w":"Reviewing","ar":"مراجعة"},{"w":"a","ar":"ـًا / واحد"},{"w":"word","ar":"كلمة"},{"w":"after","ar":"بعد"},{"w":"one","ar":"واحد"},{"w":"day","ar":"يوم"},{"w":"then","ar":"ثم"},{"w":"after","ar":"بعد"},{"w":"a","ar":"ـًا / واحد"},{"w":"week","ar":"أسبوع"},{"w":"then","ar":"ثم"},{"w":"after","ar":"بعد"},{"w":"a","ar":"ـًا / واحد"},{"w":"month","ar":"شهر"},{"w":"works","ar":"تنجح"},{"w":"much","ar":"بكثير"},{"w":"better","ar":"أفضل"},{"w":"than","ar":"من (للمقارنة)"},{"w":"studying","ar":"مذاكرة"},{"w":"it","ar":"ها (الكلمة)"},{"w":"ten","ar":"عشرة"},{"w":"times","ar":"مرات"},{"w":"in","ar":"في"},{"w":"one","ar":"واحد"},{"w":"night","ar":"ليلة"}]'::jsonb) on conflict do nothing;
insert into public.sentences (id, unit_id, position, text_en, text_ar, word_hints) values ('3d3db5de-8207-5f5b-9037-815705b34e16', '460577a1-3785-5fec-b406-ddbd8933f059', 4, 'Writing the word yourself, instead of only reading it, also helps it stick.', 'كتابة الكلمة بنفسك، بدلاً من قراءتها فقط، تساعد أيضاً على تثبيتها.', '[{"w":"Writing","ar":"يكتبون / كتابة"},{"w":"the","ar":"الـ"},{"w":"word","ar":"كلمة"},{"w":"yourself","ar":"بنفسك"},{"w":"instead","ar":"بدلاً من (instead of)"},{"w":"of","ar":"من"},{"w":"only","ar":"فقط"},{"w":"reading","ar":"قراءة"},{"w":"it","ar":"ها (الكلمة)"},{"w":"also","ar":"أيضاً"},{"w":"helps","ar":"يساعد"},{"w":"it","ar":"ها (الكلمة)"},{"w":"stick","ar":"تثبت (في الذاكرة)"}]'::jsonb) on conflict do nothing;
insert into public.questions (id, unit_id, position, prompt_en, prompt_ar, options, correct_index) values ('061d867e-295b-5db4-ba4b-747dbbd82816', '460577a1-3785-5fec-b406-ddbd8933f059', 0, 'What is the forgetting curve about?', 'عن ماذا يتحدث «منحنى النسيان»؟', '["How fast we forget new information","How to read faster","Why we need sleep","How children learn to speak"]'::jsonb, 0) on conflict do nothing;
